#!/usr/bin/env python3
"""Validate and run the IDAHO-VAULT control-plane automation registry.

This runner intentionally composes existing lane-specific validators instead of
reimplementing their doctrine. It verifies that named control-plane surfaces
exist, checks baseline JSON contracts, and runs the commands registered in the
automation registry.
"""

from __future__ import annotations

import argparse
import json
from pathlib import Path
import subprocess
import sys
from typing import Any


ROOT = Path(__file__).resolve().parents[2]
REGISTRY = ROOT / "VAULT-CONTROL-PLANE-AUTOMATION-2026-05-04.json"


def load_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def rel(path: Path) -> str:
    return str(path.relative_to(ROOT))


def validate_required_files(data: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    groups = data.get("required_files")
    if not isinstance(groups, list) or not groups:
        return ["registry: required_files must be a non-empty list"]

    for group in groups:
        if not isinstance(group, dict):
            errors.append("registry: required_files entry is not an object")
            continue
        category = group.get("category")
        paths = group.get("paths")
        if not isinstance(category, str) or not category:
            errors.append("registry: required_files entry missing category")
            continue
        if not isinstance(paths, list) or not paths:
            errors.append(f"{category}: paths must be a non-empty list")
            continue
        for path_text in paths:
            if not isinstance(path_text, str) or not path_text:
                errors.append(f"{category}: invalid path entry")
                continue
            path = ROOT / path_text
            if not path.exists():
                errors.append(f"{category}: missing {path_text}")
    return errors


def validate_json_contracts(data: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    contracts = data.get("json_contracts")
    if not isinstance(contracts, list):
        return ["registry: json_contracts must be a list"]

    for contract in contracts:
        if not isinstance(contract, dict):
            errors.append("registry: json_contract entry is not an object")
            continue
        path_text = contract.get("path")
        required_keys = contract.get("required_keys")
        if not isinstance(path_text, str) or not path_text:
            errors.append("json_contract: missing path")
            continue
        if not isinstance(required_keys, list) or not required_keys:
            errors.append(f"{path_text}: required_keys must be a non-empty list")
            continue

        path = ROOT / path_text
        if not path.is_file():
            errors.append(f"{path_text}: JSON contract file missing")
            continue
        try:
            loaded = load_json(path)
        except Exception as exc:
            errors.append(f"{path_text}: JSON parse failed: {exc}")
            continue
        if not isinstance(loaded, dict):
            errors.append(f"{path_text}: top-level JSON must be an object")
            continue
        for key in required_keys:
            if not isinstance(key, str) or not key:
                errors.append(f"{path_text}: invalid required key entry")
                continue
            if key not in loaded:
                errors.append(f"{path_text}: missing required key {key}")
    return errors


def normalize_checks(data: dict[str, Any], selected: set[str] | None) -> tuple[list[dict[str, Any]], list[str]]:
    errors: list[str] = []
    checks = data.get("checks")
    if not isinstance(checks, list) or not checks:
        return [], ["registry: checks must be a non-empty list"]

    normalized: list[dict[str, Any]] = []
    seen: set[str] = set()
    for check in checks:
        if not isinstance(check, dict):
            errors.append("registry: check entry is not an object")
            continue
        check_id = check.get("id")
        command = check.get("command")
        if not isinstance(check_id, str) or not check_id:
            errors.append("registry: check missing id")
            continue
        if check_id in seen:
            errors.append(f"{check_id}: duplicate check id")
            continue
        seen.add(check_id)
        if selected is not None and check_id not in selected:
            continue
        if (
            not isinstance(command, list)
            or not command
            or not all(isinstance(part, str) and part for part in command)
        ):
            errors.append(f"{check_id}: command must be a non-empty list of strings")
            continue
        normalized.append({"id": check_id, "command": command})

    if selected is not None:
        missing = selected - seen
        for check_id in sorted(missing):
            errors.append(f"{check_id}: selected check is not registered")
    return normalized, errors


def run_checks(checks: list[dict[str, Any]]) -> list[str]:
    failures: list[str] = []
    for check in checks:
        check_id = check["id"]
        command = check["command"]
        print(f"== {check_id} ==")
        print("$ " + " ".join(command))
        result = subprocess.run(
            command,
            cwd=ROOT,
            text=True,
            capture_output=True,
            check=False,
        )
        if result.stdout:
            print(result.stdout.rstrip())
        if result.stderr:
            print(result.stderr.rstrip(), file=sys.stderr)
        if result.returncode != 0:
            failures.append(f"{check_id}: exited {result.returncode}")
    return failures


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--list", action="store_true", help="List registered checks and exit")
    parser.add_argument(
        "--check",
        action="append",
        default=None,
        help="Run only this check id. May be repeated.",
    )
    parser.add_argument(
        "--no-run",
        action="store_true",
        help="Validate registry/files/contracts but do not execute checks.",
    )
    args = parser.parse_args()

    if not REGISTRY.is_file():
        print(f"Missing control-plane automation registry: {rel(REGISTRY)}")
        return 1

    try:
        data = load_json(REGISTRY)
    except Exception as exc:
        print(f"Control-plane automation registry parse failed: {exc}")
        return 1

    selected = set(args.check) if args.check else None
    checks, check_errors = normalize_checks(data, selected)

    if args.list:
        if check_errors:
            for error in check_errors:
                print(f"ERROR: {error}", file=sys.stderr)
            return 1
        for check in checks:
            print(check["id"])
        return 0

    errors = []
    errors.extend(validate_required_files(data))
    errors.extend(validate_json_contracts(data))
    errors.extend(check_errors)
    if errors:
        print("Vault control-plane automation violations:")
        for error in errors:
            print(f" - {error}")
        return 1

    if args.no_run:
        print("Vault control-plane automation registry OK.")
        return 0

    failures = run_checks(checks)
    if failures:
        print("Vault control-plane check failures:")
        for failure in failures:
            print(f" - {failure}")
        return 1

    print(f"Vault control-plane automation OK: {len(checks)} checks passed.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

