    ("SSH-agent assumption", re.compile(r"\bSSH_AUTH_SOCK\b|\bssh-agent\b", re.IGNORECASE)),
    ("local MCP server spawning", re.compile(r"\bmcp[-_ ]server\b|\bstart-mcp-server\b", re.IGNORECASE)),
    ("local-only absolute path", re.compile(r"/Users/|C:/Users/|C:\\\\Users\\\\")),
)

IGNORED_PARTS = {
    ".claude/plugins",
    ".claude/shell-snapshots",
    "!/CREWAI/LINKER-PROPOSAL-v1.json",
    "!/sort-audit-2026-04-16.md",
}


def rel(path: Path) -> str:
    return path.relative_to(ROOT).as_posix()


def meshweb_registry_paths() -> set[str]:
    if not MESHWEB.is_file():
        return set()

    paths: set[str] = set()
    for raw_line in MESHWEB.read_text(encoding="utf-8").splitlines():
        line = raw_line.strip()
        if not line.startswith("|"):
            continue
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if not cells or cells[0] in {"Artifact", "---"}:
            continue
        artifact = cells[0].strip("`")
        if artifact:
            paths.add(artifact)
    return paths


def iter_scan_paths() -> list[Path]:
    paths: set[Path] = set()
    for root in SCAN_ROOTS:
        if not root.exists():
            continue
        for path in root.rglob("*"):
            if not path.is_file() or path.suffix not in EXTENSIONS:
                continue
            rel_path = rel(path)
            if any(rel_path.startswith(ignored) for ignored in IGNORED_PARTS):
